"""Data coverage catalog: every field the dashboard shows, where it comes from, its license tag,
which paid / licensed source could replace it, and whether it loaded for a given ticker.

One catalog drives three things so they never drift apart:
  * the "Data Coverage" tab in the app
  * the GET /coverage/{ticker} API endpoint
  * DATA_SOURCES.md (generated by scripts/make_data_sources.py)
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Callable, Optional

import pandas as pd

from core.models import DataPoint, LicenseTag

C, D, S = LicenseTag.COMMERCIAL_OK.value, LicenseTag.DEMO_ONLY.value, LicenseTag.CALCULATED_SAFE.value

# Replacement suggestions (examples of licensed sources; final vendor choice is a business decision)
