R_EST = "Licensed estimates: LSEG I/B/E/S, FactSet Estimates, S&P Capital IQ, Zacks"
R_CAL = "Licensed earnings calendar: Wall Street Horizon, Nasdaq, Benzinga"
R_OWN = "SEC 13F filings parsed directly (free, licensed-safe) or FactSet Ownership"
R_INS = "SEC Form 4 filings parsed directly (free, licensed-safe)"
