@dataclass
class FieldSpec:
    section: str
    field: str
    source: str
    license: str
    where: str            # endpoint / tag / attribute used
    replacement: str      # what to use instead for production ("-" = already licensed-safe)
    getter: Optional[Callable[[Any], Any]] = None


# ---------------------------------------------------------------- getter helpers
def _dp(fn):
    """Getter for a DataPoint -> (loaded, preview, reason)."""
    def g(b):
        d: DataPoint = fn(b)
        if d is None:
            return False, "", "Not loaded"
        if d.available:
            v = d.value
            prev = f"{v:,.4g}" if isinstance(v, float) else str(v)[:60]
            return True, prev, ""
        return False, "", d.na_reason or "Not available"
    return g


def _val(fn, reason: str = "Not available"):
    """Getter for any value: loaded if not None / not empty."""
    def g(b):
        try:
            v = fn(b)
        except Exception:  # noqa: BLE001 - missing parent object = not loaded
            v = None
        if v is None or (isinstance(v, float) and pd.isna(v)):
            return False, "", reason
        if isinstance(v, (pd.DataFrame, pd.Series, list, dict)) and len(v) == 0:
            return False, "", reason
        if isinstance(v, (pd.DataFrame, pd.Series, list)):
            return True, f"{len(v)} rows", ""
        if isinstance(v, float):
            return True, f"{v:,.4g}", ""
        return True, str(v)[:60], ""
    return g


def _fin_field(name: str, ptype: str = "Q"):
    def fn(b):
        if b.fin is None:
            return None
        s = b.fin.series(name, ptype)
        return s if len(s) else None
    reason = "Not reported by this company"

    def g(b):
        loaded, prev, r = _val(fn, reason)(b)
        if not loaded and b.fin is not None:
            r = b.fin.na_reason(name) or r
        return loaded, prev, r
    return g


def _snap(name: str):
    return _dp(lambda b: b.analysis.snapshot.get(name) if b.analysis else None)


