def coverage_rows(bundle, safe_mode: bool = False) -> list[dict]:
    """One row per catalog field with loaded yes/no for this ticker."""
    rows = []
    for f in CATALOG:
        try:
            loaded, preview, reason = f.getter(bundle) if f.getter else (False, "", "No check")
        except Exception as exc:  # noqa: BLE001
            loaded, preview, reason = False, "", f"Error: {type(exc).__name__}"
        hidden = safe_mode and f.license == D
        rows.append({"section": f.section, "field": f.field, "source": f.source, "license_tag": f.license,
                     "loaded": bool(loaded), "shown": bool(loaded) and not hidden,
                     "preview": preview if loaded and not hidden else "",
                     "note": ("Hidden: requires a licensed data provider" if hidden and loaded else reason),
                     "where": f.where, "replacement": f.replacement})
    return rows


def coverage_summary(rows: list[dict]) -> dict:
    df = pd.DataFrame(rows)
    out = {"fields": len(df), "loaded": int(df["loaded"].sum())}
    for tag in (C, S, D):
        sub = df[df["license_tag"] == tag]
        out[tag] = {"fields": len(sub), "loaded": int(sub["loaded"].sum())}
    return out
